import { esc, icon, badge, avatar, progress, empty, fmt, money } from './ui.js';

const teams = ['Opérations', 'Investissement', 'Conformité', 'Distribution'];
const autonomy = ['Observation', 'Avec validation', 'Sous mandat', 'Autonomie étendue'];
const statusLabel = { active: 'En service', paused: 'Suspendu', pilot: 'En pilote', live: 'En service', draft: 'Brouillon' };
let orgFilter = 'all';
let teamFilter = 'all';
let processFilter = 'all';
const id = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
const status = value => badge(statusLabel[value] || value, value === 'paused' ? 'amber' : value === 'pilot' || value === 'draft' ? 'purple' : 'green');
const head = (label, title, description, actions = '') => `<header class="page-head"><div><div class="eyebrow">${label}</div><h1 class="page-title">${title}</h1><p class="page-description">${description}</p></div><div class="head-actions">${actions}</div></header>`;
const btn = (action, text, ident = '', type = '', glyph = '') => `<button class="btn ${type}" data-action="${action}" ${ident ? `data-id="${esc(ident)}"` : ''}>${glyph ? icon(glyph, 16) : ''}${text}</button>`;
const options = (values, selected = '') => values.map(v => `<option value="${esc(v)}" ${v === selected ? 'selected' : ''}>${esc(v)}</option>`).join('');
const goalName = (s, ident) => s.goals.find(g => g.id === ident)?.title || 'À rattacher à un objectif';
const managerName = (s, value) => s.agents.find(a => a.id === value)?.name || value || 'À désigner';
const agentButton = a => `<button class="person person-button" data-action="org-agent" data-id="${esc(a.id)}">${avatar(a)}<span class="person-copy"><strong>${esc(a.name)}</strong><span class="small muted">${esc(a.role)}</span></span></button>`;
const stat = (title, value, foot) => `<div class="stat-card"><div class="stat-label">${title}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;

export function renderOrganization(s) {
  const people = s.agents.filter(a => a.type === 'human');
  const agents = s.agents.filter(a => a.type === 'agent');
  const agentHours = agents.reduce((a, b) => a + b.hours, 0);
  const allHours = s.agents.reduce((a, b) => a + b.hours, 0);
  const visible = s.agents.filter(a => (orgFilter === 'all' || a.type === orgFilter) && (teamFilter === 'all' || a.team === teamFilter));
  return `${head('ORGANISATION', 'Une équipe. Des responsabilités claires.', 'Les humains donnent la direction. Chaque agent agit sous la responsabilité d’un manager identifié.', btn('org-new-agent', 'Ajouter un agent', '', 'btn-primary', 'plus'))}
  <div class="stat-grid">${stat('Votre collectif', `${people.length} <span class="stat-unit">humains</span>`, `${agents.length} agents dans les équipes`)}${stat('Travail délégué', `${Math.round(agentHours / Math.max(allHours, 1) * 100)}<span class="stat-unit">%</span>`, 'des heures suivies ce mois-ci')}${stat('Agents en service', agents.filter(a => a.status === 'active').length, `${agents.filter(a => a.status === 'pilot').length} en pilote · ${agents.filter(a => a.status === 'paused').length} suspendu(s)`)}${stat('Équipes', teams.length, 'Un responsable pour chaque mandat')}</div>
  <section class="team-grid">${teams.map((team, i) => { const actors = s.agents.filter(a => a.team === team); const humans = actors.filter(a => a.type === 'human'); const bots = actors.filter(a => a.type === 'agent'); const owner = humans.find(h=>h.role.startsWith('Responsable')) || humans[0]; return `<button class="card team-card ${teamFilter === team ? 'selected-card' : ''}" data-action="org-team-filter" data-value="${esc(team)}"><div class="row between"><span class="icon-box team-color-${i}">${icon(['activity','target','shield','users'][i])}</span>${icon('arrow', 16)}</div><h3>${team}</h3><p class="small muted">${owner ? `Sous la responsabilité de ${esc(owner.name)}` : 'Responsable à désigner'}</p><div class="team-card-foot"><span>${humans.length} humain${humans.length > 1 ? 's' : ''}</span><span class="purple-text">${bots.length} agent${bots.length > 1 ? 's' : ''}</span></div></button>`; }).join('')}</section>
  <section class="card"><div class="card-head"><div><h2 class="card-title">Les personnes et les agents</h2><p class="small muted">Une identité, un rôle et un responsable pour chacun.</p></div><span class="small muted">${visible.length} membres</span></div><div class="filter-bar">${[['all','Tout le monde'],['human','Humains'],['agent','Agents']].map(([v,t])=>`<button class="filter-btn ${orgFilter === v ? 'active' : ''}" data-action="org-type-filter" data-value="${v}">${t}</button>`).join('')}${teamFilter !== 'all' ? `<button class="filter-btn active" data-action="org-team-filter" data-value="all">${esc(teamFilter)} ${icon('x', 12)}</button>` : ''}</div>
  <div class="table-wrap"><table class="data-table"><thead><tr><th>Membre</th><th>Équipe & responsable</th><th>Statut</th><th>Qualité validée</th><th>Activité</th><th></th></tr></thead><tbody>${visible.map(a=>`<tr><td>${agentButton(a)}</td><td><span>${esc(a.team)}</span><span class="small muted cell-sub">${a.type === 'human' ? 'Responsable humain' : esc(managerName(s, a.manager))}</span></td><td>${a.type === 'human' ? badge('Humain','neutral') : status(a.status)}</td><td>${a.type === 'agent' ? `<span class="quality-number">${a.quality}%</span>${progress(a.quality,'green')}` : '<span class="muted">—</span>'}</td><td><strong>${fmt(a.hours)} h</strong><span class="small muted cell-sub">ce mois-ci</span></td><td><button class="btn btn-ghost btn-sm" aria-label="Voir ${esc(a.name)}" data-action="org-agent" data-id="${esc(a.id)}">${icon('chevron',16)}</button></td></tr>`).join('')}</tbody></table></div>${visible.length ? '' : empty('Aucun membre dans cette vue', 'Changez les filtres pour retrouver votre équipe.')}</section>`;
}

export function renderMandates(s) {
  const agents = s.agents.filter(a=>a.type==='agent');
  return `${head('DÉLÉGATION', 'L’autonomie commence par un mandat.', 'Définissez ce que chaque agent peut faire, avec quelles ressources, et quand un humain doit reprendre la main.', btn('org-autonomy-guide','Comprendre les niveaux','','btn-ghost','info'))}
  <div class="notice">${icon('shield',20)}<div><strong>Les règles de l’organisation restent prioritaires.</strong><p>Un mandat précise une délégation. Il ne permet pas de contourner une interdiction ni de s’attribuer de nouveaux droits.</p></div></div>
  <div class="grid-2 mandate-grid">${agents.map(a=>`<article class="card mandate-card"><div class="row between">${agentButton(a)}${status(a.status)}</div><div class="mandate-level"><span class="small muted">Niveau de délégation</span><strong>${autonomy[a.autonomy] || autonomy[1]}</strong><div class="autonomy-meter" aria-label="Niveau ${a.autonomy} sur 3">${[0,1,2,3].map(n=>`<span class="${n<=a.autonomy?'filled':''}"></span>`).join('')}</div></div><p class="mandate-mission">${esc(a.mandate?.mission || a.role)}</p><dl class="detail-grid"><div class="detail-item"><dt>Responsable</dt><dd>${esc(managerName(s,a.manager))}</dd></div><div class="detail-item"><dt>Révision du mandat</dt><dd>${esc(a.mandate?.expires || 'À planifier')}</dd></div><div class="detail-item full"><dt>Limites d’action</dt><dd>${esc(a.mandate?.limits || 'Validation humaine requise')}</dd></div></dl><div class="tag-list">${(a.mandate?.tools || []).slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="mandate-footer">${btn('org-edit-mandate','Modifier le mandat',a.id,'btn-sm','edit')}${btn('org-toggle-agent',a.status==='paused'?'Réactiver':'Suspendre',a.id,'btn-ghost btn-sm',a.status==='paused'?'play':'pause')}</div></article>`).join('')}</div>`;
}

export function renderProcesses(s) {
  const list = s.processes.filter(p=>processFilter==='all'||p.status===processFilter);
  return `${head('TRAVAIL COORDONNÉ', 'Du résultat attendu au travail accompli.', 'Chaque processus relie un objectif, des agents et les décisions qui restent humaines.', btn('org-new-process','Nouveau processus','','btn-primary','plus'))}
  <div class="stat-grid">${stat('Processus en service',s.processes.filter(p=>p.status==='live').length,`${s.processes.filter(p=>p.status==='draft').length} brouillon(s) à préparer`)}${stat('Dossiers traités',s.processes.reduce((n,p)=>n+p.cases,0),'sur la période de démonstration')}${stat('Décisions en attente',s.decisions.filter(d=>d.status==='pending').length,'reviennent à un responsable humain')}${stat('Exécutions simulées',s.runs.length,'aucune action dans un système externe')}</div>
  <div class="filter-bar">${[['all','Tous les processus'],['live','En service'],['draft','Brouillons'],['paused','Suspendus']].map(([v,t])=>`<button class="filter-btn ${processFilter===v?'active':''}" data-action="org-process-filter" data-value="${v}">${t}</button>`).join('')}</div>
  <div class="process-list">${list.map(p=>`<article class="card process-card"><div class="row between"><div class="row"><span class="icon-box">${icon('workflow')}</span><div><h2 class="card-title">${esc(p.name)}</h2><p class="small muted">${esc(p.team)} · ${esc(p.owner)}</p></div></div>${status(p.status)}</div><p class="process-description">${esc(p.description)}</p><div class="process-steps">${p.steps.map((step,i)=>`<div class="process-step"><span class="step-number ${step.kind==='human'?'human-step':''}">${step.kind==='human'?icon('user',13):i+1}</span><div><strong>${esc(step.name)}</strong><span>${esc(step.actor)}</span></div></div>`).join('')}</div><div class="process-card-bottom"><div class="process-metrics"><span><strong>${p.cases}</strong> dossiers</span><span><strong>${p.autonomousRate}%</strong> sous mandat</span><span><strong>${esc(p.medianTime)}</strong> délai médian</span></div><div class="row">${btn('org-process','Inspecter',p.id,'btn-sm')}${p.status==='live'?btn('org-simulate','Simuler un dossier',p.id,'btn-primary btn-sm','play'):btn('org-process','Préparer',p.id,'btn-primary btn-sm','edit')}</div></div></article>`).join('') || empty('Aucun processus dans cette vue','Essayez un autre filtre.')}</div>`;
}

export function renderIntegrations(s) {
  return `${head('CONNEXIONS', 'La gouvernance, reliée à l’exécution.', 'Le démonstrateur fonctionne avec des données fictives. Temporal et Mastra sont les cibles d’intégration prévues.',btn('org-export-contract','Exporter le contrat JSON','','btn-primary','download'))}
  <div class="notice">${icon('info',20)}<div><strong>Mode démonstration locale</strong><p>Les décisions et modifications sont conservées dans ce navigateur. Aucun moteur, modèle ou système métier n’est connecté.</p></div></div>
  <div class="grid-2 integration-grid"><article class="card integration-card"><div class="row between"><div class="integration-logo temporal-logo">T</div>${badge('Non connecté','neutral')}</div><h2>Temporal</h2><p class="muted">État durable des processus, attentes humaines et reprise du travail.</p><div class="tag-list"><span class="tag">Workflow</span><span class="tag">Décisions</span><span class="tag">Événements</span></div><ul class="integration-list"><li>${icon('check',15)} Corréler chaque dossier à un workflow</li><li>${icon('check',15)} Transmettre une décision vérifiée</li><li>${icon('check',15)} Suivre les délais et les exceptions</li></ul>${btn('org-integration-detail','Voir le contrat d’intégration','temporal','btn-sm','arrow')}</article><article class="card integration-card"><div class="row between"><div class="integration-logo mastra-logo">m.</div>${badge('Non connecté','neutral')}</div><h2>Mastra</h2><p class="muted">Agents, outils et appels soumis à la délégation du responsable humain.</p><div class="tag-list"><span class="tag">Agents</span><span class="tag">Outils</span><span class="tag">Approbations</span></div><ul class="integration-list"><li>${icon('check',15)} Fournir le mandat applicable à l’agent</li><li>${icon('check',15)} Vérifier les droits avant une action</li><li>${icon('check',15)} Remonter résultats et justificatifs</li></ul>${btn('org-integration-detail','Voir le contrat d’intégration','mastra','btn-sm','arrow')}</article></div>
  <section class="card"><div class="card-head"><div><h2 class="card-title">Un contrat commun de gouvernance</h2><p class="small muted">Les objets métier existent dans l’application. Leur transport vers les moteurs reste à implémenter.</p></div>${icon('plug')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Objet</th><th>Responsabilité</th><th>État du démonstrateur</th></tr></thead><tbody><tr><td><strong>Mandat</strong></td><td>Identité, propriétaire, outils, limites et niveau d’autonomie</td><td>${badge('Éditable','green')}</td></tr><tr><td><strong>Demande de décision</strong></td><td>Action précise, preuves, responsable et issue</td><td>${badge('Interactif','green')}</td></tr><tr><td><strong>Exécution</strong></td><td>Processus, étapes, événements et attente humaine</td><td>${badge('Simulée','purple')}</td></tr><tr><td><strong>Journal</strong></td><td>Historique des modifications et arbitrages</td><td>${badge('Local','neutral')}</td></tr><tr><td><strong>Synchronisation</strong></td><td>Authentification serveur, événements et contrôle d’accès</td><td>${badge('À connecter','amber')}</td></tr></tbody></table></div></section>`;
}

function agentDrawer(a,s,ctx) {
  const g = s.goals.find(g=>g.id===a.objectiveId);
  const pending = s.decisions.filter(d=>d.agentId===a.id&&d.status==='pending');
  ctx.drawer({title:a.name,subtitle:`${a.role} · ${a.team}`,body:`<div class="row between">${avatar(a)}${a.type==='agent'?status(a.status):badge('Responsable humain','neutral')}</div><div class="separator"></div><div class="detail-grid"><div class="detail-item"><dt>Responsable</dt><dd>${esc(managerName(s,a.manager))}</dd></div><div class="detail-item"><dt>Activité ce mois-ci</dt><dd>${fmt(a.hours)} heures</dd></div>${a.type==='agent'?`<div class="detail-item"><dt>Qualité validée</dt><dd>${a.quality}%</dd></div><div class="detail-item"><dt>Coût observé</dt><dd>${money(a.cost)}</dd></div>`:''}</div><h3 class="section-title">Mission</h3><p>${esc(a.mandate?.mission||a.role)}</p><h3 class="section-title">Compétences</h3><div class="tag-list">${(a.skills||[]).map(skill=>`<span class="tag">${esc(skill)}</span>`).join('')}</div>${g?`<h3 class="section-title">Objectif auquel il contribue</h3><div class="card"><strong>${esc(g.title)}</strong>${progress(g.progress)}<span class="small muted">${g.progress}% de progression</span></div>`:''}${a.type==='agent'?`<h3 class="section-title">Délégation</h3><p><strong>${autonomy[a.autonomy]}</strong></p><p class="muted">${esc(a.mandate?.limits||'Validation humaine requise.')}</p><div class="row">${btn('org-edit-mandate','Modifier le mandat',a.id,'btn-primary','edit')}${btn('org-toggle-agent',a.status==='paused'?'Réactiver':'Suspendre',a.id,'btn-ghost',a.status==='paused'?'play':'pause')}</div>`:''}${pending.length?`<div class="notice"><div>${pending.length} décision(s) attendent un arbitrage pour ce membre.${btn('org-open-decisions','Voir les décisions','','btn-sm')}</div></div>`:''}`});
}

function editMandate(a,s,ctx) {
 ctx.closeDrawer();
 ctx.modal({title:`Mandat de ${a.name}`,subtitle:'La modification est enregistrée dans le journal de gouvernance.',body:`<div class="field"><label for="mandate-mission">Mission confiée</label><textarea id="mandate-mission" name="mission" required rows="3">${esc(a.mandate?.mission||a.role)}</textarea></div><div class="form-grid"><div class="field"><label for="mandate-manager">Responsable humain</label><select name="manager" id="mandate-manager">${options(s.agents.filter(x=>x.type==='human').map(x=>x.name),managerName(s,a.manager))}</select></div><div class="field"><label for="mandate-level">Niveau d’autonomie</label><select id="mandate-level" name="autonomy">${autonomy.map((t,i)=>`<option value="${i}" ${a.autonomy===i?'selected':''}>${i} — ${t}</option>`).join('')}</select></div></div><div class="field"><label for="mandate-limits">Limites et escalades</label><textarea id="mandate-limits" name="limits" rows="3" required>${esc(a.mandate?.limits||'')}</textarea></div><div class="field"><label for="mandate-tools">Outils autorisés</label><input id="mandate-tools" name="tools" value="${esc((a.mandate?.tools||[]).join(', '))}" placeholder="Séparer les outils par une virgule"><div class="form-help">Ces autorisations sont illustratives ; aucun accès externe n’est créé.</div></div><div class="field"><label for="mandate-expires">Date de révision</label><input id="mandate-expires" name="expires" type="date" required value="${esc(/^\d{4}-\d{2}-\d{2}$/.test(a.mandate?.expires||'')?a.mandate.expires:'2026-12-31')}"></div>`,submitLabel:'Enregistrer le mandat',onSubmit:fd=>{
  const level=Number(fd.get('autonomy'));
  if(!Number.isInteger(level)||level<0||level>3){ctx.toast('Choisissez un niveau de délégation valide.');return false;}
  const result=ctx.setAutonomy(a.id,level); if(result?.ok===false){ctx.toast(result.error||'Délégation refusée.');return false;}
  ctx.update(st=>{const actor=st.agents.find(x=>x.id===a.id);actor.manager=String(fd.get('manager'));actor.mandate={...actor.mandate,mission:String(fd.get('mission')).trim(),limits:String(fd.get('limits')).trim(),tools:String(fd.get('tools')).split(',').map(t=>t.trim()).filter(Boolean),expires:String(fd.get('expires')),reviewer:String(fd.get('manager'))};},'Mandat mis à jour',`${a.name} · responsable : ${fd.get('manager')}`);ctx.toast('Le mandat a été mis à jour.');
 }});
}

function processDrawer(p,s,ctx) {
 const runs=s.runs.filter(r=>r.processId===p.id);
 ctx.drawer({title:p.name,subtitle:`${p.team} · ${p.owner}`,body:`${status(p.status)}<p>${esc(p.description)}</p><div class="detail-grid"><div class="detail-item"><dt>Objectif</dt><dd>${esc(goalName(s,p.goalId))}</dd></div><div class="detail-item"><dt>Responsable</dt><dd>${esc(p.owner)}</dd></div></div><h3 class="section-title">Responsabilités par étape</h3><div class="timeline">${p.steps.map(step=>`<div class="timeline-item"><span class="icon-box">${icon(step.kind==='human'?'user':step.kind==='control'?'shield':'bot',16)}</span><div><strong>${esc(step.name)}</strong><p class="small muted">${esc(step.actor)} · ${step.kind==='human'?'Décision humaine':step.kind==='control'?'Contrôle':'Agent sous mandat'}</p></div></div>`).join('')}</div><h3 class="section-title">Agents affectés</h3><div class="stack">${p.agentIds.map(aid=>s.agents.find(a=>a.id===aid)).filter(Boolean).map(agentButton).join('')}</div><div class="separator"></div><div class="row">${p.status==='live'?btn('org-simulate','Simuler un dossier',p.id,'btn-primary','play'):''}${btn('org-toggle-process',p.status==='live'?'Suspendre le processus':'Mettre en service',p.id,'btn-ghost',p.status==='live'?'pause':'play')}</div><h3 class="section-title">Exécutions récentes</h3>${runs.length?runs.slice().sort((a,b)=>new Date(b.startedAt)-new Date(a.startedAt)).slice(0,5).map(r=>`<div class="card run-summary"><div class="row between"><strong>${esc(r.id)}</strong>${badge(({waiting:'Décision requise',completed:'Terminé',rejected:'Refusé',running:'En cours'})[r.status]||r.status,r.status==='completed'?'green':r.status==='waiting'?'amber':'neutral')}</div><div class="timeline">${r.events.map(e=>`<div class="timeline-item"><span class="status-dot"></span><div><strong>${esc(e.title)}</strong><p class="small muted">${esc(e.detail)}</p></div></div>`).join('')}</div></div>`).join(''):empty('Aucune exécution','Lancez un dossier de démonstration pour suivre ses étapes.')}`});
}

function downloadContract(s) {
 const contract={schema:'alto-govern.execution-contract.v1',mode:'demonstration',generatedAt:new Date().toISOString(),workspace:s.settings.workspace,description:'Contrat cible illustratif. Aucun transport Temporal ou Mastra implémenté.',agents:s.agents.filter(a=>a.type==='agent').map(a=>({agentId:a.id,owner:a.manager,autonomy:a.autonomy,mandate:a.mandate})),processes:s.processes.map(p=>({processId:p.id,goalId:p.goalId,agentIds:p.agentIds,steps:p.steps})),policies:s.policies,events:{request:'governance.decision.requested',response:'governance.decision.resolved',mandateChanged:'governance.mandate.changed',agentSuspended:'governance.agent.suspended'},decisionEnvelope:{decisionId:'string',workflowId:'string',agentId:'string',actionFingerprint:'sha256 of exact proposed action',policyVersion:'string',reviewerIdentity:'verified server-side',outcome:'approved | rejected',reason:'string',decidedAt:'ISO8601'}};
 const url=URL.createObjectURL(new Blob([JSON.stringify(contract,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='alto-govern-contrat-execution.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

export function handleOrganization(action,el,ctx) {
 if(!action.startsWith('org-'))return false;
 const s=ctx.getState();const ident=el.dataset.id;const actor=s.agents.find(a=>a.id===ident);const process=s.processes.find(p=>p.id===ident);
 if(action==='org-type-filter'){orgFilter=el.dataset.value;ctx.render();}
 else if(action==='org-team-filter'){teamFilter=teamFilter===el.dataset.value?'all':el.dataset.value;ctx.render();}
 else if(action==='org-process-filter'){processFilter=el.dataset.value;ctx.render();}
 else if(action==='org-agent'&&actor)agentDrawer(actor,s,ctx);
 else if(action==='org-edit-mandate'&&actor)editMandate(actor,s,ctx);
 else if(action==='org-open-decisions'){ctx.closeDrawer();ctx.navigate('decisions');}
 else if(action==='org-toggle-agent'&&actor){const next=actor.status==='paused'?(['active','pilot'].includes(actor.previousStatus)?actor.previousStatus:'active'):'paused';ctx.update(st=>{const target=st.agents.find(a=>a.id===ident);if(next==='paused')target.previousStatus=target.status;else delete target.previousStatus;target.status=next;},next==='paused'?'Agent suspendu':'Agent réactivé',actor.name);ctx.closeDrawer();ctx.toast(next==='paused'?`${actor.name} est suspendu. Les nouvelles simulations sont bloquées.`:`${actor.name} est de nouveau en service.`);}
 else if(action==='org-autonomy-guide')ctx.drawer({title:'Quatre niveaux de délégation',subtitle:'Une responsabilité humaine à chaque niveau.',body:autonomy.map((name,i)=>`<div class="card"><h3>${i} — ${name}</h3><p class="muted">${['L’agent observe les données de démonstration et prépare des analyses. Il n’exécute aucune action.','Les actions sont soumises au responsable avant exécution.','L’agent agit dans un périmètre défini. Les exceptions reviennent au responsable.','L’agent dispose d’une délégation plus large, dans les limites explicites du mandat et des règles de l’organisation.'][i]}</p></div>`).join('')});
 else if(action==='org-new-agent')ctx.modal({title:'Accueillir un nouvel agent',subtitle:'Attribuez-lui une mission et un responsable. Il commencera en pilote.',body:`<div class="form-grid"><div class="field"><label for="agent-name">Nom de l’agent</label><input id="agent-name" name="name" placeholder="Ex. Horizon" required maxlength="40"></div><div class="field"><label for="agent-role">Rôle</label><input id="agent-role" name="role" placeholder="Ex. Analyste de reporting" required maxlength="80"></div><div class="field"><label for="agent-team">Équipe</label><select id="agent-team" name="team">${options(teams)}</select></div><div class="field"><label for="agent-manager">Responsable humain</label><select id="agent-manager" name="manager">${options(s.agents.filter(a=>a.type==='human').map(a=>a.name))}</select></div></div><div class="field"><label for="agent-mission">Mission</label><textarea id="agent-mission" name="mission" rows="3" placeholder="Quel résultat doit-il produire ?" required></textarea></div><div class="field"><label for="agent-skills">Compétences</label><input id="agent-skills" name="skills" placeholder="Analyse, rédaction, contrôle…"><div class="form-help">Séparez les compétences par une virgule.</div></div><div class="field"><label for="agent-objective">Objectif</label><select id="agent-objective" name="objectiveId">${s.goals.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select></div>`,submitLabel:'Créer l’agent en pilote',onSubmit:fd=>{const name=String(fd.get('name')).trim();if(!name){ctx.toast('Le nom est requis.');return false;}if(s.agents.some(a=>a.name.toLowerCase()===name.toLowerCase())){ctx.toast('Ce nom existe déjà.');return false;}ctx.update(st=>st.agents.push({id:id('agent'),name,initials:name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase(),role:String(fd.get('role')).trim(),type:'agent',team:String(fd.get('team')),manager:String(fd.get('manager')),status:'pilot',autonomy:1,quality:0,hours:0,cost:0,skills:String(fd.get('skills')).split(',').map(v=>v.trim()).filter(Boolean),objectiveId:String(fd.get('objectiveId')),mandate:{mission:String(fd.get('mission')).trim(),tools:[],limits:'Validation humaine requise avant toute action.',expires:'2026-12-31',reviewer:String(fd.get('manager'))}}),'Agent créé en pilote',name);ctx.toast(`${name} a rejoint l’équipe en pilote.`);}});
 else if(action==='org-process'&&process)processDrawer(process,s,ctx);
 else if(action==='org-simulate'&&process){try{const result=ctx.simulateProcess(ident);if(result?.ok===false){ctx.toast(result.error||'La simulation est bloquée.');return true;}ctx.toast('Dossier simulé : consultez les étapes et la décision humaine.');processDrawer(ctx.getState().processes.find(p=>p.id===ident),ctx.getState(),ctx);}catch(error){ctx.toast(error.message||'Simulation impossible.');}}
 else if(action==='org-toggle-process'&&process){const next=process.status==='live'?'paused':'live';if(next==='live'&&process.agentIds.some(aid=>s.agents.find(a=>a.id===aid)?.status==='paused')){ctx.toast('Réactivez les agents suspendus avant de démarrer ce processus.');return true;}ctx.update(st=>st.processes.find(p=>p.id===ident).status=next,next==='live'?'Processus mis en service':'Processus suspendu',process.name);ctx.closeDrawer();ctx.toast(next==='live'?'Processus disponible pour simulation.':'Processus suspendu.');}
 else if(action==='org-new-process')ctx.modal({title:'Définir un processus',subtitle:'Décrivez le résultat attendu, puis attribuez ses responsabilités.',body:`<div class="field"><label for="process-name">Nom du processus</label><input id="process-name" name="name" required placeholder="Ex. Préparer le reporting mensuel"></div><div class="field"><label for="process-description">Résultat attendu</label><textarea id="process-description" name="description" rows="3" required></textarea></div><div class="form-grid"><div class="field"><label for="process-team">Équipe</label><select id="process-team" name="team">${options(teams)}</select></div><div class="field"><label for="process-owner">Responsable</label><select id="process-owner" name="owner">${options(s.agents.filter(a=>a.type==='human').map(a=>a.name))}</select></div></div><div class="field"><label for="process-agent">Agent principal</label><select id="process-agent" name="agentId">${s.agents.filter(a=>a.type==='agent').map(a=>`<option value="${esc(a.id)}">${esc(a.name)} — ${esc(a.role)}</option>`).join('')}</select></div><div class="field"><label for="process-goal">Objectif rattaché</label><select id="process-goal" name="goalId">${s.goals.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select></div>`,submitLabel:'Créer le brouillon',onSubmit:fd=>{const assigned=s.agents.find(a=>a.id===fd.get('agentId'));ctx.update(st=>st.processes.push({id:id('process'),name:String(fd.get('name')).trim(),description:String(fd.get('description')).trim(),owner:String(fd.get('owner')),team:String(fd.get('team')),agentIds:[assigned.id],goalId:String(fd.get('goalId')),status:'draft',cases:0,autonomousRate:0,medianTime:'—',steps:[{name:'Préparer le dossier',actor:assigned.name,kind:'agent'},{name:'Vérifier les règles',actor:'Gouvernance',kind:'control'},{name:'Valider le résultat',actor:String(fd.get('owner')),kind:'human'}]}),'Processus créé',String(fd.get('name')));ctx.toast('Brouillon créé. Inspectez-le pour le mettre en service.');}});
 else if(action==='org-export-contract'){downloadContract(s);ctx.toast('Contrat JSON exporté.');}
 else if(action==='org-integration-detail')ctx.drawer({title:ident==='temporal'?'Contrat Temporal':'Contrat Mastra',subtitle:'Spécification cible · connecteur non implémenté',body:`<div class="notice"><div>Aucun endpoint ni identifiant n’est configuré. Les échanges ci-dessous décrivent le raccordement à réaliser.</div></div><h3 class="section-title">${ident==='temporal'?'De la décision au workflow':'Du mandat à l’action'}</h3><div class="timeline">${(ident==='temporal'?[['Créer le dossier','Associer processId, workflowId et version du mandat.'],['Demander un arbitrage','Recevoir l’action exacte, les preuves et l’identité du responsable.'],['Enregistrer la décision','Vérifier les droits côté serveur et lier la décision à l’action présentée.'],['Reprendre l’exécution','Transmettre une décision idempotente et récupérer l’état du workflow.']]:[['Charger le mandat','Transmettre la mission, les limites et les outils autorisés.'],['Contrôler avant exécution','Appliquer les règles hors du modèle, avant chaque effet externe.'],['Suspendre si nécessaire','Créer une demande de décision avec les arguments exacts de l’outil.'],['Rapporter le résultat','Publier le résultat accepté, les justificatifs et le coût.']]).map(([t,d],i)=>`<div class="timeline-item"><span class="step-number">${i+1}</span><div><strong>${t}</strong><p class="small muted">${d}</p></div></div>`).join('')}</div>${btn('org-export-contract','Télécharger le contrat JSON','','btn-primary','download')}`});
 else return false;
 return true;
}
